css:
.dmx-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.dmx-root,.dmx-root *,.dmx-root *::before,.dmx-root *::after{box-sizing:border-box}
.dmx-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.dmx-root img{display:block;border:0;max-width:none}
.dmx-root > [data-node-id]{will-change:transform}
.dmx-root [hidden]{display:none!important}
.dmx-root [data-sh-theme="light"]{display:none!important}
.dmx-root[data-theme="light"] [data-sh-theme="light"]{display:block!important}
.dmx-root[data-theme="light"] [data-sh-theme="dark"]{display:none!important}
.dmx-root .dmx_n2857_3726{position:absolute;display:contents;inset:29.63% 1.67% 65.93% 14.17%}
.dmx-root .dmx_n2857_3727{position:absolute;background-color:var(--wa-surface, #494949);inset:29.63% 1.67% 65.93% 14.17%}
.dmx-root .dmx_n2857_3728{position:absolute;background-color:var(--wa-surface, #202529);inset:29.63% 80% 65.93% 14.17%}
.dmx-root .dmx_n2857_3736{word-break:break-word;position:absolute;font-family:"NanumGothic","Pretendard",sans-serif;font-weight:700;inset:30.74% 67.33% 67.96% 20.6%;line-height:14px;font-style:normal;font-size:14px;color:var(--wa-text, #fff);width:231.75px;white-space:nowrap}
.dmx-root .dmx_n2857_3737{word-break:break-word;position:absolute;font-family:"Nanum Gothic","Pretendard",sans-serif;font-weight:700;inset:30.72% 78.29% 67.98% 14.99%;line-height:14px;font-style:normal;font-size:12px;color:var(--wa-text, #fff);width:129.18px;white-space:nowrap}
.dmx-root[data-theme="light"] [data-name="Badge/Gas Level"] p{color:var(--wa-text, #fff)!important}
.dmx-root[data-theme="light"] [data-name="Badge/Critical"] p,.dmx-root[data-theme="light"] [data-name^="status-critical"] p,.dmx-root[data-theme="light"] [data-name="Count/Critical"] p{color:var(--wa-danger, #ad152d)!important;font-weight:600;white-space:nowrap}
.dmx-root[data-theme="light"] [data-name="Badge/Major"] p,.dmx-root[data-theme="light"] [data-name^="status-major"] p,.dmx-root[data-theme="light"] [data-name="Count/Major"] p{color:var(--wa-warn, #8f3f00)!important;font-weight:600;white-space:nowrap}
.dmx-root[data-theme="light"] [data-name="Badge/Minor"] p,.dmx-root[data-theme="light"] [data-name^="status-minor"] p,.dmx-root[data-theme="light"] [data-name="Count/Minor"] p{color:var(--wa-warn, #6b4d00)!important;font-weight:600;white-space:nowrap}
.dmx-root[data-theme="light"] [data-name="Badge/Warning"] p,.dmx-root[data-theme="light"] [data-name^="status-warning"] p,.dmx-root[data-theme="light"] [data-name="Count/Warning"] p{color:var(--wa-point, #1356b3)!important;font-weight:600;white-space:nowrap}
.dmx-root[data-theme="light"] [data-name="Badge/Normal"] p,.dmx-root[data-theme="light"] [data-name^="status-normal"] p,.dmx-root[data-theme="light"] [data-name="Count/Normal"] p{color:var(--wa-text-sub, #4b5868)!important;font-weight:600;white-space:nowrap}
.dmx-root[data-theme="light"] [data-name="Button/Ack"] p,.dmx-root[data-theme="light"] [data-name="Button/Ack All"] p,.dmx-root[data-theme="light"] [data-name="Button/Reset"] p{color:var(--wa-text, #fff)!important}
.dmx-root [data-name="Header"] > [data-name="Bullet"]:has(> [data-name="Base"]){transform-origin:0 4px;transform:translate(4px,-4px) scaleY(0.8889)}
.dmx-root [data-name="Event Log"] [data-name="Toolbar"] [data-name="Bullet"] > [data-name]{translate:2px 0}
.dmx-root [data-name="Header"] > [data-name="Bullet"]:not(:has(> [data-name="Base"])){transform-origin:0 1.83px;transform:translate(2px,-4.17px) scaleY(0.8649)}
.dmx-root[data-theme="light"] [data-name="Nav"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 60%, transparent)!important}
.dmx-root{position:absolute;inset:0;background:transparent;z-index:auto;overflow:visible}
.dmx-root > [data-node-id="2857:3672"]{width:1920px;height:1080px}
.dmx-root[data-theme="light"]{color:var(--wa-point, #15253a)}
.dmx-root[data-theme="light"] [data-name="Logo Group"] [data-name="Title"]{background-image:linear-gradient(to right,var(--wa-point, #1d4fc4),var(--wa-point, #3a7ee6))!important}
.dmx-root[data-theme="light"] [data-name="Clock"] [data-name="Time"]{background-image:linear-gradient(to top,var(--wa-point, #173f9e),var(--wa-point, #2e72dc) 86.843%)!important}
.dmx-root[data-theme="light"] [data-name="Symbol"] > [data-name="Shape"] img{opacity:.32;filter:saturate(.7)}
.dmx-root[data-theme="light"] :is([data-name="Floor Layer"],[data-name="Floor"] > [data-name="Part"]) > *{opacity:.18}
.dmx-root[data-theme="light"] [data-name="Floor"] img{opacity:.25}
.dmx-root[data-theme="light"] [data-name="Effect"] > * > *,.dmx-root[data-theme="light"] [data-name="Effect"] img{opacity:.45}
.dmx-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) img{content:normal!important}
.dmx-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) p{color:var(--wa-text, #fff)!important}
.dmx-root[data-theme="light"] [data-name="Button/Stop"]{background:var(--wa-point, #1668d4)!important}
.dmx-root[data-theme="light"] [data-name="Button/Own"]{background:var(--wa-point, #2d6bd6)!important}
.dmx-root[data-theme="light"] [data-name="Button/Ack"]{background:var(--wa-point, #24489f)!important}
.dmx-root[data-theme="light"] [data-name="Button/Select"]{background:var(--wa-point, #1f6fd8)!important}
.dmx-root[data-theme="light"] .dmx_n2857_3727{background-color:var(--wa-surface, #cfd1d5)}
.dmx-root[data-theme="light"] .dmx_n2857_3728{background-color:var(--wa-bg, #e7e8ea)}
.dmx-root[data-theme="light"] .dmx_n2857_3736{color:var(--wa-point, #0f2238)}
.dmx-root[data-theme="light"] .dmx_n2857_3737{color:var(--wa-point, #0f2238)}
.dmx-root[data-theme="light"] [data-node-id="2857:3674"]{background-image:linear-gradient(to right,var(--wa-bg, #e4ebf4) 48.714%,var(--wa-point, #bccbdd))!important;box-shadow:inset 0 -1px 0 #b3c3d6}
